INSERT INTO purpose VALUES('workflow-host-tools','build::Built','enum','Names what a build did for a job, so whether the key stood or the build wrote it is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::Processes','struct','Runs each command of a build as a process with its output in one log, so a failed command''s output is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::Pruned','enum','Names what a prune did with the scratch, so whether it removed it, met a build or found none is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::Runner','trait','Runs the commands of a build, so a test builds a key with no compiler.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::build','function','Builds one tool into its key whole or not at all, under the key''s lock, so a key that stands is read as a whole build.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::key','function','Names the directory of a job''s key, so where a tool''s build stands is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::prune','function','Removes the scratch of the builds when no build holds it, so the builder''s disk holds no scratch at rest.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','build::retire','function','Removes the keys of a tool''s other versions with their markers, so the builder holds one key for each tool and target.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','error::HostToolsError','enum','Names why a tool could not be planned or built, so the refusal''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','host::Host','struct','Holds the builder''s linkers, C tools, programs and receivers, so the host facts of a cross-build and a push are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','host::Receiver','struct','Holds a host that receives the keys of its target, with its mise''s data directory and path, so where a push copies a key is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','host::TargetTools','struct','Holds the linker and the C tools of one target, so a build''s variables are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','input::Input','struct','Holds a file a reader reads, with its path for a refusal, so the table, the lock and the configuration are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','jobs::Job','struct','Holds one tool to build for one target, with its version and its install name, so a build''s subject is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','jobs::MISE','constant','Names the key of mise itself in the table, so the tool whose version is the pin is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','jobs::plan','function','Gives the jobs of a target, one for each tool the table builds for it, so what a target''s build builds is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::Entry','struct','Holds one tool of mise''s listing at one version, with its install state and path, so whether a host holds it is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::Inspection','enum','Names what an install holds: no program, a program of another machine, or programs that fit, so a lack''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::Lack','enum','Names a tool that a host lacks and why, so a job stops with one line that names the tool, its version and the platform.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::Listing','struct','Holds mise''s listing of a checkout''s tools, so the check reads each tool and its install.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::Machine','struct','Names the machine of an ELF program, so a binary of another architecture counts as lacking.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::Source','struct','Names the configuration that pins a tool of mise''s listing, so a tool that a host pins for itself stays out of the checkout''s check.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::disabled','function','Reads the tools that a host disables, so the tools of a backend that needs one of them stay out of the check.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::inspect','function','Reads what an install holds, so an install with no program or with a program of another machine is found.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lack::lacks','function','Gives each tool of a checkout that a host lacks, so a job on a receiver stops before it uses a tool that does not run there.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','lock::Lock','struct','Holds the version `mise.lock` locks for each tool, so a tool''s version is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::GoArch','enum','Names an architecture as Go names it, so a Go build''s architecture is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::HostName','struct','Names a host as ssh names it, so the destination of a push is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::InstallName','struct','Names a tool''s directory in mise''s install directory, so a key copies into that directory as it is.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Json','struct','Holds a text of JSON as mise prints it, so the check reads mise''s answers.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Placeholder','struct','Names the text a clone''s files hold in place of the version, so a stamp''s subject is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Platform','struct','Names a host''s system and architecture, so a line of the check names the platform that lacks a tool.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::ProgramName','struct','Names a program that a build runs, so its path in the host''s configuration is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::RemotePath','struct','Names a path on a receiver relative to its home, so where a push writes on that host is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Repository','struct','Names a git repository, so a clone''s source is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Target','struct','Names a target triple, so the target of a build is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Template','struct','Holds a text in which a placeholder stands for the version, so a tag or linker flags at a version are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::ToolKey','struct','Names a tool by its key in `mise.toml`, so the tool of a build is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','names::Version','struct','Names a version of a tool, so the version a build builds is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','push::MISE_DATA','constant','Names the data directory of a receiver''s mise when its configuration names none, so where a key goes by default is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','push::Pushed','enum','Names what a push did for a key or an update, so whether a copy ran, stood or did not apply is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','push::push','function','Copies a key into a receiver''s mise install directory once, under a marker, so a host runs the builder''s build of a tool.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','push::settle','function','Turns mise''s automatic installs off on a receiver once, under a marker, so mise installs no binary of another machine there.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','push::update','function','Brings a host''s mise to the pin once, under a marker, so each host runs the version of mise that the tree pins.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','recipe::Builds','struct','Holds the table of the tools to build, so the tools of a target are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','recipe::Recipe','enum','Names one way to build a tool, so a build''s commands are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','recipe::Stamp','struct','Holds the placeholder a clone''s files hold in place of the version, so a build from a tag reports its version.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','recipe::Tool','struct','Holds one tool of the table with its targets, its recipe and the programs it needs, so a tool''s build is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','steps::Run','struct','Holds one command of a build, so its program, arguments, variables and directory are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','steps::Step','enum','Names one step of a build, so the order of a build''s commands and stamps is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('workflow-host-tools','steps::steps','function','Gives the steps that build a job, so how a recipe builds is read.',NULL,'fits','sound',NULL);
